  fframes_apart F B FF -> (forall b, In b LB -> F + B <= fst b \/ fst b + snd b <= F) ->
  (F <= a < F + B \/ S F <= a <= S (F + B - 1)) -> ~ aclient L ar LB FF sp scr a.
